import{c as t,Q as r,j as e,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Session Insight — Dynamic Workflow 實戰 × 雙版規則集打造的踩坑與學習","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-05-session-insight-dynamic-workflow-dual-ruleset.md","filePath":"research/reports/2026-06-05-session-insight-dynamic-workflow-dual-ruleset.md","lastUpdated":1780842316000}'),n={name:"research/reports/2026-06-05-session-insight-dynamic-workflow-dual-ruleset.md"};function a(i,o,l,d,g,c){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="session-insight-—-dynamic-workflow-實戰-×-雙版規則集打造的踩坑與學習" tabindex="-1">Session Insight — Dynamic Workflow 實戰 × 雙版規則集打造的踩坑與學習 <a class="header-anchor" href="#session-insight-—-dynamic-workflow-實戰-×-雙版規則集打造的踩坑與學習" aria-label="Permalink to &quot;Session Insight — Dynamic Workflow 實戰 × 雙版規則集打造的踩坑與學習&quot;">​</a></h1><blockquote><p><strong>日期</strong>：2026-06-05 · <strong>原始分支</strong>：<code>feature/dual-ruleset-12rule</code> · <strong>模型</strong>：Opus 4.8 (1M) · ultracode mode <strong>任務脈絡</strong>：把 12-Rule Canon 改寫成「Claude Code 特化 + 通用」雙版本 × 三等級，後續再去 workspace 化 + 重構為可延展 Harness 框架。 <strong>本報告性質</strong>：第一人稱 session 復盤（agent 自身的執行軌跡），非外部研究。§1–§4.7/§5(1–7) 的踩坑與數字來自原始 session（<code>feature/dual-ruleset-12rule</code>）實際發生，非文獻。 <strong>產出 commit</strong>：原始 session <code>f014b703</code>（雙版三等級初版）→ <code>562631e0</code>（去 workspace 化 + 可延展重構）。<strong>後續 append</strong>：§3.5 + §5(8)（D4 verifier PoC 踩坑）由後續 session 於分支 <code>feature/ruleset-audit-fixes</code>（commit <code>fcc9e9ba</code>）補入。</p></blockquote><hr><h2 id="_0-執行摘要-給趕時間的人" tabindex="-1">0. 執行摘要（給趕時間的人） <a class="header-anchor" href="#_0-執行摘要-給趕時間的人" aria-label="Permalink to &quot;0. 執行摘要（給趕時間的人）&quot;">​</a></h2><p>本 session 用 Dynamic Workflow 做了兩件 fan-out 工作（tier 收斂驗證、去 workspace 化重寫），最大的學習<strong>不在 workflow 本身，而在「何時該用、何時是陷阱」</strong>：</p><ol><li><strong>最大踩坑 = CJK byte-grind 陷阱</strong>：為把「完整版」壓進一個 <strong>後來被使用者要求移除的 19K cap</strong>，手動逐行刪了 ~20 輪、每輪只回收 6–40 byte，還因此削掉了 3 條規則的 mechanical check（製造出「vibe 非 rule」）。<strong>根因：把一個 workspace 客製約束當成了普世硬約束。</strong></li><li><strong>Dynamic Workflow 的真正價值 = 並行的確定性轉換 + 對抗式驗證</strong>，不是「讓 agent 想內容」。本 session workflow 表現最好的時刻是「我給定已驗證的內容、agent 只做 de-workspace 轉換 + 獨立 grep 審計」；表現最差的風險是「讓 agent 重新推導論文數字」（會重新引入已修正的 3 個錯誤）。</li><li><strong>advisor 是這個 session 的 MVP</strong>：在 3 個關鍵轉折點（staged-not-overwrite / 19K-cap-是-workspace-think / 完整版自我描述矛盾）攔截了會毀掉交付物的決策。<strong>advisor 看完整 transcript 的價值，遠高於任何 sub-agent 的 self-report。</strong></li><li><strong>使用者的 3 次漸進指令重新定義了任務</strong>：從「改寫」→「去 workspace 化」→「可延展框架」。每次都讓更多手工打磨白工。<strong>學習：規格模糊度是工作量的天花板（R1.1），但使用者漸進澄清是常態，過早大量手工優化是賭注。</strong></li></ol><hr><h2 id="_1-session-時間軸-從開始到完成" tabindex="-1">1. Session 時間軸（從開始到完成） <a class="header-anchor" href="#_1-session-時間軸-從開始到完成" aria-label="Permalink to &quot;1. Session 時間軸（從開始到完成）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>階段</th><th>動作</th><th>結果 / 踩坑</th></tr></thead><tbody><tr><td><strong>Orientation</strong></td><td>讀 5 份報告 + best-practices + deepened-ruleset；advisor 第一次諮詢</td><td>advisor 鎖定 6 約束，最關鍵：<strong>staged deliverable 非 in-place overwrite</strong>（mid-session 改 live CLAUDE.md 破壞並行 session 共享 cache）。避開了第一個大坑。</td></tr><tr><td><strong>建 master</strong></td><td>手寫完整版 5 檔（含全 Rn.x 子條）</td><td>27,122 byte → 遠超假想的 19K cap。<strong>第一個錯誤判斷在此萌芽</strong>。</td></tr><tr><td><strong>byte-grind</strong></td><td>為壓進 19K，手動逐行刪 ~20 輪</td><td>每輪回收 6–40 byte（CJK 密度高）；削掉 R2.1/R4.1/R8.1 的 check；引入過 <code>||</code> 非標準 markdown table。<strong>最大時間黑洞</strong>。</td></tr><tr><td><strong>Workflow #1</strong></td><td>tier 收斂 + 對抗驗證（3 builders + 9 verifiers）</td><td>lite/standard 成功；<strong>full builder 沒跑/卡住</strong> → 我手動接管 full 的壓縮。學習：workflow 部分失敗時主對話要能無縫接管。</td></tr><tr><td><strong>使用者指令 1</strong></td><td>「Claude 版帶太多 workspace 東西，移除 19K cap/SKILL/script/hook」</td><td><strong>19K cap 整個消失</strong> → byte-grind 全成白工。advisor 點明：cap 本就是 workspace-think。</td></tr><tr><td><strong>使用者指令 2</strong></td><td>「通用版也去 workspace 化 + 全面改寫，12 準則只是參考」</td><td>從 patch 升級為 rewrite。</td></tr><tr><td><strong>使用者指令 3</strong></td><td>「不受限 12 準則 + 可擴充 + 揉合論文與最佳實踐 = 可延展 Harness 雙版」</td><td>任務本質重定義為「<strong>可延展框架</strong>」非「固定規則集」。</td></tr><tr><td><strong>Workflow #2</strong></td><td>去 workspace 化 + 加延展性（6 rewrites + ref 清理 + 2 audits）</td><td><strong>成功</strong>：rule 檔全清、延展性 framing 全加、cap 移除後<strong>順手修復了 advisor 指出的 Rn.x 缺 check 缺陷</strong>（每子條補回獨立驗）。</td></tr><tr><td><strong>收尾</strong></td><td>grep 驗零殘留 + healthcheck FAIL=0 + commit</td><td>零 workspace token、零 number-regression。</td></tr></tbody></table><hr><h2 id="_2-踩坑深掘-每個都附根因-防範" tabindex="-1">2. 踩坑深掘（每個都附根因 + 防範） <a class="header-anchor" href="#_2-踩坑深掘-每個都附根因-防範" aria-label="Permalink to &quot;2. 踩坑深掘（每個都附根因 + 防範）&quot;">​</a></h2><h3 id="踩坑-1-—-cjk-byte-grind-陷阱-最貴" tabindex="-1">踩坑 1 — CJK Byte-Grind 陷阱（最貴） <a class="header-anchor" href="#踩坑-1-—-cjk-byte-grind-陷阱-最貴" aria-label="Permalink to &quot;踩坑 1 — CJK Byte-Grind 陷阱（最貴）&quot;">​</a></h3><p><strong>現象</strong>：把完整版從 27K 手動壓到 18,994（≤19K）花了 ~20 個工具回合，每次 Edit 只回收 6–40 byte。中文 token 密度高 → 每行刪減的 byte 報酬極低。</p><p><strong>根因</strong>：① 把 <strong>workspace 客製的 19K cap 當普世硬約束</strong>；② 已經陷入逐行優化後，沒有退一步問「這個約束本身對嗎」。advisor 早就說過「cap 是 what you choose to run 的屬性」，但我在 grind 中沒回連這句話。</p><p><strong>代價</strong>：不只是時間。為省 byte 削掉了 R2.1/R4.1/R8.1 的 mechanical check → 製造出「有 prevents、無 check」的 sub-clause = canon 自己禁止的「vibe 非 rule」。<strong>用降低交付物品質換一個假約束。</strong></p><p><strong>防範</strong>：</p><ul><li><strong>質疑約束再優化</strong>：逐行壓縮前先問「這個數字/限制是哪來的、對這個交付物適用嗎」。staged template 的 byte 數 ≠ live config 的 cap。</li><li><strong>結構槓桿 &gt; 逐行槓桿</strong>：超標 2K 時，正解是「把深度移進 on-demand ref」（一次結構調整），不是「逐行刪 40 byte ×50 次」。</li><li><strong>削減不可碰 canon 的可驗證性</strong>：byte 壓力下若要削內容，先削 rationale/citation prose，<strong>絕不削 mechanical check</strong>——check 是規則的本質。</li></ul><h3 id="踩坑-2-—-把-sub-agent-workflow-verdict-當證據" tabindex="-1">踩坑 2 — 把 Sub-Agent / Workflow Verdict 當證據 <a class="header-anchor" href="#踩坑-2-—-把-sub-agent-workflow-verdict-當證據" aria-label="Permalink to &quot;踩坑 2 — 把 Sub-Agent / Workflow Verdict 當證據&quot;">​</a></h3><p><strong>現象</strong>：Workflow #1 的 full-builder 回報沒問題但實際沒改檔；標準 builder 把 standard 壓到 14,872（低於我設的 floor）。</p><p><strong>根因</strong>：dynamic workflow 會幻覺（workspace 既有 lesson）。Verdict 是 self-report，不是 ground truth。</p><p><strong>防範（已是 workspace 鐵律，本 session 再次驗證有效）</strong>：每個 workflow 階段後<strong>主對話親自 grep 重驗</strong>。本 session 的 number-regression grep、leakage grep、防/驗 count 全是我自己跑，不信 workflow 的 audit verdict。<strong>這條救了交付物</strong>——workflow audit agent 報「clean」但我 grep 出 harness-loop.md 還有 6 個 workspace token。</p><h3 id="踩坑-3-—-refs-的隱藏汙染-差點漏掉" tabindex="-1">踩坑 3 — Refs 的隱藏汙染（差點漏掉） <a class="header-anchor" href="#踩坑-3-—-refs-的隱藏汙染-差點漏掉" aria-label="Permalink to &quot;踩坑 3 — Refs 的隱藏汙染（差點漏掉）&quot;">​</a></h3><p><strong>現象</strong>：我 grep 了 rule 檔說「乾淨」，但 advisor 點出<strong>我沒 grep 已 ship 的 refs</strong>。<code>harness-loop.md</code> 是從 live repo 逐字複製的，滿是 <code>/autoload-evolution</code>、<code>gap-vote</code>、<code>measure.sh</code>、<code>memory-compactor</code>。</p><p><strong>根因</strong>：把「複製現成 ref」當零成本，忘了 ref 也是交付物的一部分、也帶 workspace 耦合。</p><p><strong>防範</strong>：交付物的<strong>每個檔案</strong>（含複製來的 ref/附件）都要過同一套 leakage 審計。「複製」不等於「乾淨」。</p><h3 id="踩坑-4-—-過早大量手工優化-賭規格不變" tabindex="-1">踩坑 4 — 過早大量手工優化（賭規格不變） <a class="header-anchor" href="#踩坑-4-—-過早大量手工優化-賭規格不變" aria-label="Permalink to &quot;踩坑 4 — 過早大量手工優化（賭規格不變）&quot;">​</a></h3><p><strong>現象</strong>：在 byte-grind 投入 ~20 回合後，使用者指令 1 直接移除了 19K cap → 全部白工。</p><p><strong>根因</strong>：規格在演進中（使用者 3 次漸進澄清），我在規格未定時就做了大量不可攤銷的手工打磨。</p><p><strong>防範</strong>：R1.1（規格優先於資源）的延伸——<strong>規格還在動時，先做骨架與結構決策（可攤銷），延後逐行打磨（不可攤銷）</strong>。byte-grind 是典型「規格未定就 all-in 的不可攤銷工作」。</p><h3 id="踩坑-5-—-bash-hook-慣例反覆觸發" tabindex="-1">踩坑 5 — Bash hook 慣例反覆觸發 <a class="header-anchor" href="#踩坑-5-—-bash-hook-慣例反覆觸發" aria-label="Permalink to &quot;踩坑 5 — Bash hook 慣例反覆觸發&quot;">​</a></h3><p><strong>現象</strong>：<code>perl -i</code>、<code>F=...</code>（VAR= 開頭）、<code>cd &amp;&amp; bash</code> 三次被 block-dangerous hook 擋下。</p><p><strong>根因</strong>：忘了 workspace 的 Bash 慣例（repo root 用絕對路徑、不以 VAR= 開頭、不 cd）。</p><p><strong>防範</strong>：這正是「hook 作為確定性 gate」的價值——它擋下的不是錯誤命令，是<strong>我沒內化的慣例</strong>。教訓：環境的 hook 慣例要在第一次被擋後立即內化，不要重複觸發。</p><hr><h2 id="_3-dynamic-workflow-的收穫-使用者特別想知道的" tabindex="-1">3. Dynamic Workflow 的收穫（使用者特別想知道的） <a class="header-anchor" href="#_3-dynamic-workflow-的收穫-使用者特別想知道的" aria-label="Permalink to &quot;3. Dynamic Workflow 的收穫（使用者特別想知道的）&quot;">​</a></h2><h3 id="_3-1-什麼時候-workflow-真的贏" tabindex="-1">3.1 什麼時候 workflow 真的贏 <a class="header-anchor" href="#_3-1-什麼時候-workflow-真的贏" aria-label="Permalink to &quot;3.1 什麼時候 workflow 真的贏&quot;">​</a></h3><p>本 session 兩個 workflow，<strong>第二個（去 workspace 化）遠比第一個（byte 收斂）成功</strong>。差異很有啟發：</p><table tabindex="0"><thead><tr><th>維度</th><th>Workflow #1（byte 收斂）</th><th>Workflow #2（去 workspace 化）</th></tr></thead><tbody><tr><td>任務性質</td><td>壓到模糊的 byte 目標（規格在動）</td><td>確定性轉換（移除 token list + 加固定段落）</td></tr><tr><td>Agent 自由度</td><td>高（要自己決定砍哪裡）→ 易偏移</td><td>低（給定 removal list + 已驗證內容）→ 穩</td></tr><tr><td>結果</td><td>部分失敗（full builder 沒跑）</td><td>全成功</td></tr><tr><td><strong>學習</strong></td><td><strong>workflow 不擅長「對著動態目標做判斷密集的優化」</strong></td><td><strong>workflow 擅長「對著固定 spec 做並行的機械轉換 + 獨立審計」</strong></td></tr></tbody></table><p><strong>核心收穫</strong>：Dynamic Workflow 的甜蜜點是**「寬度」而非「深度判斷」**——當工作可以拆成 N 個獨立、規格明確的轉換 + 對抗式驗證時，並行 fan-out 省下大量 wall-clock。當工作需要「對著移動的目標反覆判斷取捨」時，主對話直接做反而穩。</p><h3 id="_3-2-workflow-的對抗式驗證-pattern-值得複用" tabindex="-1">3.2 Workflow 的對抗式驗證 pattern（值得複用） <a class="header-anchor" href="#_3-2-workflow-的對抗式驗證-pattern-值得複用" aria-label="Permalink to &quot;3.2 Workflow 的對抗式驗證 pattern（值得複用）&quot;">​</a></h3><p>第二個 workflow 用了 <code>Rewrite → Audit</code> 兩階段：6 個 rewrite agents 各改自己的 tier，再 2 個 audit agents <strong>各自獨立 grep</strong> workspace token / number-regression / canon coverage，輸出 structured verdict。</p><p><strong>但關鍵紀律</strong>：我<strong>沒有信</strong> audit 的 <code>pass=true</code>，而是主對話自己再 grep 一次——並抓到 harness-loop.md 殘留。<strong>對抗式驗證提升信心，但不取代主對話的最終親驗。</strong></p><h3 id="_3-3-餵-trace-而非-score-保護已驗證的事實" tabindex="-1">3.3 餵 trace 而非 score；保護已驗證的事實 <a class="header-anchor" href="#_3-3-餵-trace-而非-score-保護已驗證的事實" aria-label="Permalink to &quot;3.3 餵 trace 而非 score；保護已驗證的事實&quot;">​</a></h3><p>最重要的 workflow 紀律：<strong>給 agent 已驗證的內容讓它轉換，不讓它重新推導事實</strong>。本 session 有 3 個論文數字曾被 sub-agent 誤植（ACE −82.6% 不存在 / TTFT 13–31% 應為 22.9% / MetaGPT −40% 為二手）。我在 workflow prompt 裡明列「PROTECTED / FORBIDDEN 變體」，並在每個 audit agent 加 number-regression grep。<strong>結果：零回歸。</strong> 若放任 rewrite agent「順便改善措辭」，極可能重新引入這 3 個錯誤。</p><h3 id="_3-4-workflow-成本誠實" tabindex="-1">3.4 Workflow 成本誠實 <a class="header-anchor" href="#_3-4-workflow-成本誠實" aria-label="Permalink to &quot;3.4 Workflow 成本誠實&quot;">​</a></h3><p>兩個 workflow 跑了 ~20 個 sub-agent。ultracode mode 下 token 不是約束，但若非 ultracode，<strong>第一個 workflow（byte 收斂）其實不值得</strong>——那個工作主對話自己做更快更穩。<strong>workflow 不是「越多越好」，是「寬度任務才划算」。</strong></p><h3 id="_3-5-後續延伸-2026-06-05-d4-verifier-poc-—-「確定性層經-workflow-agent-中介就不再確定性」" tabindex="-1">3.5 後續延伸（2026-06-05 D4 verifier PoC）— 「確定性層經 workflow agent 中介就不再確定性」 <a class="header-anchor" href="#_3-5-後續延伸-2026-06-05-d4-verifier-poc-—-「確定性層經-workflow-agent-中介就不再確定性」" aria-label="Permalink to &quot;3.5 後續延伸（2026-06-05 D4 verifier PoC）— 「確定性層經 workflow agent 中介就不再確定性」&quot;">​</a></h3><blockquote><p>脈絡：本報告原始 session（<code>feature/dual-ruleset-12rule</code>）merge 後，<strong>後續 session</strong>（分支 <code>feature/ruleset-audit-fixes</code>，非同一分支）據研究 lever D4（Anthropic 官方「one verifier per rule」）建了個 Hybrid per-rule verifier PoC（verifier 提 verdict + 確定性 grep 裁決）。第三個 workflow（12 agent：6 verify + 6 adjudicate），揭露一個<strong>比 §3.2 更深的新踩坑</strong>。詳見 <code>2026-06-05-d4-per-rule-verifier-poc.md</code>。</p></blockquote><p><strong>踩坑 6 — 把「確定性裁決」實作成 workflow agent stage，它就不再確定性。</strong></p><p><strong>現象</strong>：PoC 的 adjudicate stage 委派 sub-agent 跑 <code>adjudicate.sh</code>（已 self-validate 6/6 的確定性腳本）。workflow 回報 <code>mechanicalVsGroundTruth: 4/6</code>——2 個 known-good 被判 FAIL exit=2。但<strong>主對話親自跑同一腳本 = 6/6 全對</strong>。</p><p><strong>根因（grep 鐵證，非臆測）</strong>：workflow 內腳本<strong>無 shell/FS 直接存取</strong>，只能透過非確定性 agent 的 Bash 觸達。那條路徑被 <code>block-dangerous.sh</code> hook 擋下（<code>First word detected: &#39;adjudicate.sh&#39;</code>，連 <code>bash &lt;path&gt;</code> retry 也 BLOCKED）。agent <strong>忠實回報</strong>了 hook 的 exit=2（<strong>沒腦補、沒誤報</strong>）——但那不是裁決邏輯的輸出。</p><p><strong>這比 §3.2 更深的地方</strong>：§3.2 的教訓是「不信 audit agent 的 <code>pass=true</code>，主對話再 grep」——針對的是 agent <strong>判斷</strong> verdict。踩坑 6 證明：<strong>連「確定性層」經 agent 中介都會失真</strong>。不是 agent 騙你，是<strong>執行環境（hook gate / PATH / sandbox）污染了本應確定性的結果</strong>。所以「我跑的是確定性 grep 啊」不足以信任——<strong>重點是誰跑的</strong>：主對話親自跑才是 ground truth，workflow sub-agent 跑的「確定性」結果一樣要被主對話親自驗。</p><p><strong>防範（正確架構，PoC 已驗證）</strong>：</p><ul><li><strong>verify = workflow fan-out</strong>（判斷密集、找 suspect、產<strong>可機械複驗的 inspectable claim</strong> → agent 適任，本 PoC 6/6 成立）。</li><li><strong>adjudicate = 主對話 / 真實 hook / CI</strong>（確定性裁決 → <strong>絕不</strong>經 sub-agent）。</li><li>判別：問「這個 stage 的輸出若被 hook 擋/缺工具/環境變了，會不會靜默變成假結果？」會 → 那不是能交給 sub-agent 的「確定性」工作。</li></ul><p><strong>這 PoC 諷刺地自我示範了它要證明的紀律</strong>：它本是為「強化 auto-load 規則遵循率驗證」而建，結果第一手撞上的就是「even mechanical verdict 經 agent 中介不可信」——正是 #439 + dynamic-workflow 紀律的最強佐證。<strong>唯一可信的 mechanical verdict 是主對話親自跑的那個。</strong></p><hr><h2 id="_4-對-claude-code-各元件的認識與強化建議" tabindex="-1">4. 對 Claude Code 各元件的認識與強化建議 <a class="header-anchor" href="#_4-對-claude-code-各元件的認識與強化建議" aria-label="Permalink to &quot;4. 對 Claude Code 各元件的認識與強化建議&quot;">​</a></h2><blockquote><p>本 session 密集使用了 advisor / Workflow / hooks / sub-agents / skills / CLAUDE.md / refs。以下是對每個元件的實戰認識 + 落地建議。</p></blockquote><h3 id="_4-1-claude-md-auto-load-規則" tabindex="-1">4.1 CLAUDE.md / auto-load 規則 <a class="header-anchor" href="#_4-1-claude-md-auto-load-規則" aria-label="Permalink to &quot;4.1 CLAUDE.md / auto-load 規則&quot;">​</a></h3><ul><li><strong>認識</strong>：CLAUDE.md 是 <strong>advisory context 非 enforced config</strong>（官方：no guarantee of strict compliance）。過長 → reduce adherence（規則被噪音淹沒）。本 session 親身驗證：規則檔越想塞滿，越要靠 byte-grind 搶救，治標不治本。</li><li><strong>強化建議</strong>： <ol><li><strong>分級載入策略 &gt; 單一大檔</strong>：把規則拆成「always-load 骨架 + on-demand refs 深度」。本 session 三等級的正解最終就是這個（lite 骨架 / full + refs）。</li><li><strong>每條規則附 mechanical check</strong>：無 check 的規則是 vibe，模型遵循率低。這是本交付物的核心設計，也適用於任何人的 CLAUDE.md。</li><li><strong>byte/行數是『報告值』非『設計約束』</strong>：除非有實證的 cap，不要為湊一個數字犧牲規則可驗證性（本 session 最痛的教訓）。</li></ol></li></ul><h3 id="_4-2-hooks" tabindex="-1">4.2 Hooks <a class="header-anchor" href="#_4-2-hooks" aria-label="Permalink to &quot;4.2 Hooks&quot;">​</a></h3><ul><li><strong>認識</strong>：hook 是<strong>確定性 gate</strong>，與 CLAUDE.md 的 advisory 本質互補。本 session 的 block-dangerous hook 三次擋下我違反 Bash 慣例的命令——它擋的不是「危險」，是「我沒內化的慣例」。</li><li><strong>強化建議</strong>： <ol><li><strong>確定性需求一律交 hook，不要寫進 CLAUDE.md</strong>（「commit 前必跑 X」「禁某操作」）——CLAUDE.md 不保證遵循。</li><li><strong>hook 在共用資源上必 fail-open（warn 不 block）</strong>：多 session / 背景自動化共用同一 hook，exit 2 會連帶 block 別人。</li><li><strong>hook 錯誤訊息要可操作</strong>：block-dangerous 的訊息有「First word detected / To allow this」——這讓我能立即修正而非卡住。好的 hook = 好的錯誤訊息。</li></ol></li></ul><h3 id="_4-3-sub-agents-dynamic-workflow" tabindex="-1">4.3 Sub-Agents / Dynamic Workflow <a class="header-anchor" href="#_4-3-sub-agents-dynamic-workflow" aria-label="Permalink to &quot;4.3 Sub-Agents / Dynamic Workflow&quot;">​</a></h3><ul><li><strong>認識</strong>：見 §3。核心：<strong>寬度任務的並行轉換 + 對抗驗證是甜蜜點；深度判斷密集的動態優化是陷阱</strong>。Verdict 永遠是 self-report 非 ground truth。</li><li><strong>強化建議</strong>： <ol><li><strong>委派門檻要嚴</strong>：未達「≥10 檔 / &gt;20 tool call / ≥3 獨立子任務」就主對話直接做。本 session 第一個 workflow 違反了這條（byte 優化不是寬度任務）。</li><li><strong>給 agent 已驗證的事實 + 明列 forbidden 變體</strong>：防止「順便改善」重新引入已修正的錯誤。</li><li><strong>workflow 後主對話必親 grep 重驗</strong>：對抗式 audit 提升信心不取代親驗。本 session 靠這條抓到 ref 殘留。</li><li><strong>part-failure 接管</strong>：workflow 部分 agent 失敗時，主對話要能無縫接手（本 session full-builder 失敗後我手動接管）。</li></ol></li></ul><h3 id="_4-4-advisor" tabindex="-1">4.4 advisor <a class="header-anchor" href="#_4-4-advisor" aria-label="Permalink to &quot;4.4 advisor&quot;">​</a></h3><ul><li><strong>認識</strong>：本 session 的 MVP。advisor 看<strong>完整 transcript</strong>，在 3 個關鍵轉折攔截毀滅性決策：staged-not-overwrite、19K-cap-是-workspace-think、完整版自我描述矛盾。它的價值正在於「看到我看不到的全局」。</li><li><strong>強化建議</strong>： <ol><li><strong>大量不可逆/不可攤銷工作前必諮詢 advisor</strong>：byte-grind 那 20 回合若早一步問 advisor「這 cap 對 staged template 適用嗎」，能省下全部白工。</li><li><strong>advisor 指出但我『騎過去』的點要回頭結算</strong>：本 session 完整版 R6 缺 check 的問題，我在 grind 中標了「acceptable 但記一下」然後騎過去——advisor 在 done-check 又抓回來。<strong>「記一下然後繼續」是技術債，advisor 會記得。</strong></li><li><strong>advisor ≠ rubber stamp</strong>：它給的是 discriminating check，不是背書。</li></ol></li></ul><h3 id="_4-5-skills" tabindex="-1">4.5 Skills <a class="header-anchor" href="#_4-5-skills" aria-label="Permalink to &quot;4.5 Skills&quot;">​</a></h3><ul><li><strong>認識</strong>：skill 是<strong>按需載入的深度知識 / workflow</strong>，與 advisory 規則互補。本 session 沒重度用 skill，但去 workspace 化時發現「規則檔引用 skill 名」是耦合源——skill 名是 workspace 特定的。</li><li><strong>強化建議</strong>：通用規則集不要 hardcode skill 名（<code>/haiku-pilot</code> 等）；用能力描述（「依任務複雜度選模型」）取代具名 skill 呼叫，才能跨 workspace 移植。</li></ul><h3 id="_4-6-refs-on-demand-參考" tabindex="-1">4.6 refs（on-demand 參考） <a class="header-anchor" href="#_4-6-refs-on-demand-參考" aria-label="Permalink to &quot;4.6 refs（on-demand 參考）&quot;">​</a></h3><ul><li><strong>認識</strong>：refs 是「深度知識放這、不佔每 session 前綴」的機制。本 session 學到：<strong>ref 也是交付物，複製來的 ref 一樣帶耦合</strong>（harness-loop.md 踩坑）。</li><li><strong>強化建議</strong>： <ol><li><strong>ref 是延後深度的正解</strong>：完整版的 Rn.x 全深度放 ref，骨架放 auto-load——這是「結構槓桿」勝「byte-grind」的體現。</li><li><strong>複製的 ref 必過同套審計</strong>：別假設現成 ref 乾淨。</li></ol></li></ul><h3 id="_4-7-context-management-本-session-自身的-context-紀律" tabindex="-1">4.7 Context Management（本 session 自身的 context 紀律） <a class="header-anchor" href="#_4-7-context-management-本-session-自身的-context-紀律" aria-label="Permalink to &quot;4.7 Context Management（本 session 自身的 context 紀律）&quot;">​</a></h3><ul><li><strong>認識</strong>：本 session 很長（多次 compact 風險）。staged deliverable 全程寫進檔案（durable），不靠 context 記憶——這讓 compact / session 中斷不致丟工作。</li><li><strong>強化建議</strong>：長 session 的交付物<strong>邊做邊落檔</strong>（先 Write 再 advisor 再 commit），不把成果留在 context。本 session 兩次 commit（f014b703 / 562631e0）都在宣告完成前先讓交付物 durable。</li></ul><hr><h2 id="_5-可遷移的-meta-learnings-跨-session-通用" tabindex="-1">5. 可遷移的 meta-learnings（跨 session 通用） <a class="header-anchor" href="#_5-可遷移的-meta-learnings-跨-session-通用" aria-label="Permalink to &quot;5. 可遷移的 meta-learnings（跨 session 通用）&quot;">​</a></h2><ol><li><strong>質疑約束再優化</strong>：逐行優化前先確認約束本身成立。最痛的白工來自「對著一個假約束努力」。</li><li><strong>結構槓桿 &gt; 逐行槓桿</strong>：超標就移結構（depth→ref），不要逐行刮。CJK 環境尤其——逐行刮的 byte 報酬極低。</li><li><strong>規格未定時做可攤銷的、延後不可攤銷的</strong>：骨架/結構可攤銷（規格變了還能用），逐行打磨不可攤銷（規格變了全廢）。使用者漸進澄清是常態。</li><li><strong>Verdict 非證據，主對話必親驗</strong>：sub-agent / workflow / 甚至自己上一輪的產物，都要 grep 重驗。</li><li><strong>advisor 的『記一下然後繼續』是技術債</strong>：被指出的缺陷要當場結算或明確排程，不要騎過去——它會在 done-check 回來。</li><li><strong>Workflow 甜蜜點 = 寬度（並行確定性轉換 + 對抗驗證），非深度（動態判斷優化）</strong>。</li><li><strong>每條規則/每個交付物元件都要可機械驗證</strong>：無 check 的規則是 vibe；無 grep 的「乾淨」是猜測。</li><li><strong>「確定性」是執行者的屬性，不是腳本的屬性</strong>（2026-06-05 D4 PoC）：同一個 self-validate 6/6 的確定性腳本，主對話親自跑 = 6/6，經 workflow sub-agent 中介跑 = 4/6（被 hook 擋成 exit=2）。第 4 點是「不信 agent 的<strong>判斷</strong> verdict」；第 8 點更深——<strong>連 agent 轉述的「確定性」結果都不可信</strong>，因執行環境（hook/PATH/sandbox）會污染。架構含義：<strong>adjudicate 絕不經 sub-agent</strong>，確定性 gate 只在主對話/真實 hook/CI 成立。</li></ol><hr><h2 id="_6-數據附錄-本-session-實測" tabindex="-1">6. 數據附錄（本 session 實測） <a class="header-anchor" href="#_6-數據附錄-本-session-實測" aria-label="Permalink to &quot;6. 數據附錄（本 session 實測）&quot;">​</a></h2><ul><li>雙版交付物：2 版 × 3 等級 + refs + README = 24 檔。</li><li>Claude 版 byte（去 cap 後，內容範圍分級）：lite 11,146 / standard 15,658 / full 25,388。</li><li>通用版 byte：lite 3.8K / standard 11.5K / full 14.4K + ref。</li><li>Workflow 用量：2 個 workflow、~20 sub-agent。</li><li>byte-grind 回合數：~20（每輪 6–40 byte，最痛的反模式）。</li><li>advisor 諮詢：5 次，攔截 3 個毀滅性決策 + 1 個 done-check 缺陷。</li><li>驗證 gate：workspace token 零殘留 · number-regression 零回歸 · 6 版本全有延展性 framing · healthcheck FAIL=0。</li><li>commit：f014b703（初版）→ 562631e0（去 workspace + 可延展）。</li></ul><hr><blockquote><p><strong>一句話總結</strong>：這個 session 最大的學習不是「Dynamic Workflow 很強」，而是「<strong>Workflow 在寬度任務上很強、在深度判斷優化上是陷阱；而所有 agent 產物——含 workflow——都是 self-report 非 ground truth，主對話的親 grep 與 advisor 的全局視角才是最後防線</strong>」。byte-grind 的 20 回合白工，是「對假約束努力 + 過早不可攤銷優化」的教科書案例，值得每次大量手工打磨前回看。</p></blockquote>',80)])])}const k=t(n,[["render",a]]);export{u as __pageData,k as default};
